package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paiflow.domain.*;
import com.ruoyi.paiflow.mapper.RunMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.paiflow.service.ModelOperationPorts.*;

/** 原历史金样＋真实历史/模型MyBatis事务；目录/身份/模型响应隔离，不是Provider或页面验收。 */
class JavaModelHistoryOperationTest {
    JavaRunHistoryPersistenceTest f;
    ManagedModelInvocationPolicy policy;
    ModelOperationService calls,target;
    ModelRuntimeCatalog catalog;
    AtomicReference<PrivateGrant> grant=new AtomicReference<>();
    java.util.concurrent.atomic.AtomicInteger dispatches=new java.util.concurrent.atomic.AtomicInteger();
    @BeforeEach void setup()throws Exception {
        f=new JavaRunHistoryPersistenceTest();f.setup();
        catalog=mock(ModelRuntimeCatalog.class);var fixed=mock(ModelRuntimeCatalog.FixedModel.class);
        when(catalog.resolvePinned(anyLong(),anyLong(),eq("model:1:version:2"),any())).thenReturn(fixed);
        when(fixed.provider()).thenReturn("openai");when(fixed.domain()).thenReturn("original-model");when(fixed.modelVersionId()).thenReturn(2L);when(fixed.capabilities()).thenReturn(Set.of("chat"));
        when(fixed.credentialRef()).thenReturn("isolated-history-reference");when(fixed.credentialVersion()).thenReturn("1");when(fixed.privateBaseUrl()).thenReturn("https://no-network.invalid/v1");
        var runtime=mock(ManagedModelRuntime.class);var profile=new ModelRuntimeProperties.Profile();profile.setEnabled(true);profile.setInvocationAllowed(true);profile.setRuntimeProvider("openai");profile.setSourceProvider("openai-compatible");profile.setDomain("original-model");profile.setCredentialRef("isolated-history-reference");profile.setAllowedUserIds(List.of(42L));profile.setAllowedSpaceIds(List.of(1L));profile.setProviderDefaultMaxTokens(128);profile.setMaxCalls(20);profile.setMaxTokens(1000000);profile.setMaxRequestBytes(ModelOperationJson.REQUEST_BYTES);profile.setTimeoutSeconds(300);when(runtime.profile(fixed)).thenReturn(profile);
        policy=new ManagedModelInvocationPolicy(runtime,catalog,f.models);policy.useHistory(JavaRunHistoryPersistenceTest.provider(f.service),f.runs);
        f.sources.useHistory(JavaRunHistoryPersistenceTest.provider(f.service));
        target=new ModelOperationService(f.models,f.runs,f.spaces,f.leases,catalog);target.useCompletedSources(f.sources);target.useHistory(JavaRunHistoryPersistenceTest.provider(f.service));
        calls=proxy(target);
        var credentials=new CredentialMaterialPort(){public boolean available(ModelRuntimeCatalog.FixedModel m){return true;}public PrivateMaterial resolve(ModelRuntimeCatalog.FixedModel m){return new PrivateMaterial(m.credentialRef(),m.credentialVersion(),m.privateBaseUrl(),"isolated-history-key");}};
        var bridge=new ProducerBridge(){public boolean available(ModelRuntimeCatalog.FixedModel m){return true;}public DispatchAck submit(PrivateGrant g,ProducerCallbacks cb){assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());dispatches.incrementAndGet();grant.set(g);return new DispatchAck(g.operationId(),g.grantId(),true);}public StopEvidence stop(String operation,String g,String reason){return null;}};
        target.usePorts(JavaRunHistoryPersistenceTest.provider(policy),JavaRunHistoryPersistenceTest.provider(credentials),JavaRunHistoryPersistenceTest.provider(bridge),JavaRunHistoryPersistenceTest.provider(calls));
    }
    <T>T proxy(T value){var p=new org.springframework.aop.framework.ProxyFactory(value);p.setProxyTargetClass(true);p.addAdvice(new org.springframework.transaction.interceptor.TransactionInterceptor(new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.db),new org.springframework.transaction.annotation.AnnotationTransactionAttributeSource()));return (T)p.getProxy();}
    @AfterEach void close()throws Exception {f.close();}
    RunRecord run(int rounds,boolean open)throws Exception {
        var r=f.run("值",f.params("系统{{x}}","问题{{x}}",rounds),JavaRunHistoryPersistenceTest.CHAT,42,1,2);r.setDeadline(LocalDateTime.ofInstant(Instant.now().plusSeconds(300),ZoneOffset.UTC));
        var t=ModelMessageSources.sourceObject(r.getAssignmentJson());r.setModelPermitJson(RunJsonBoundary.canonicalFull(calls.admit(r.getId(),42,1,3,t.getString("dslHash"),t.getJSONObject("input"),t.getJSONObject("resourceSnapshots"),t.getJSONObject("dsl"),r.getDeadline().toInstant(ZoneOffset.UTC),"java")));if(open)f.open(r);return r;
    }
    JSONObject request(RunRecord r){var proof=f.snapshot(r);return JSONObject.of("leaseId",r.getLeaseId(),"attempt",1,"nodeId",JavaRunHistoryPersistenceTest.NODE,"iterationId",null,"operation","model.invoke","idempotencyKey","history_"+r.getId(),"parameters",JSONObject.of("resourceId","model:1:version:2","resourceVersion","2","provider","openai","modelName","original-model","mode","chat","messages",proof.get("messages"),"options",JavaModelSemantics.options(f.node(r))));}
    CallCandidate candidate(ModelOperationRecord row)throws Exception {var method=ModelOperationService.class.getDeclaredMethod("callCandidate",JSONObject.class);method.setAccessible(true);return (CallCandidate)method.invoke(null,ModelMessageSources.sourceObject(row.getApprovalJson()).getJSONObject("candidate"));}
    void prior()throws Exception {var r=f.run("旧问",f.params("旧系统","旧用户",0),JavaRunHistoryPersistenceTest.CHAT,42,1,2);f.open(r);var op=f.model(r,"旧回答","不发送的旧思考",false);f.service.completeJava(r.getId(),JavaRunHistoryPersistenceTest.NODE,op.getId());}
    JSONArray frames(boolean length)throws Exception{return JSON.parseArray(JavaRunHistoryPersistenceTest.resource("/fixtures/java-model-wire/original-sdk.json")).getJSONObject(length?4:0).getJSONArray("rawFrames");}
    void commit(boolean length)throws Exception {var raw=frames(length);long seq=0;for(Object item:raw)calls.commitFrame(grant.get(),++seq,(JSONObject)item);calls.finishStream(grant.get(),seq,seq-1,length?"length":"stop");}
    JSONObject zeroRequest(RunRecord run){return JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"nodeId",JavaRunHistoryPersistenceTest.NODE,"iterationId",null,"operation","model.invoke","idempotencyKey","legacy_"+run.getId(),"parameters",JSONObject.of("resourceId","model:1:version:2","resourceVersion","2","provider","openai","modelName","original-model","mode","chat","messages",JavaModelSemantics.messages(f.node(run),f.inputs(run),new JSONArray()),"options",JavaModelSemantics.options(f.node(run))));}
    Object completedAnswer(RunRecord run,JSONArray raw){
        var projection=JavaModelSemantics.projection(raw);var assignment=ModelMessageSources.sourceObject(run.getAssignmentJson());var event=ModelOperationJson.copy(f.original.getJSONArray("actualEvents").stream().map(v->(JSONObject)v).filter(v->"node.completed".equals(v.get("eventType"))&&JavaRunHistoryPersistenceTest.NODE.equals(v.get("nodeId"))).findFirst().orElseThrow());
        event.put("runId",run.getId());event.put("leaseId",run.getLeaseId());event.put("seq",3);var result=event.getJSONObject("payload").getJSONObject("result");result.put("inputs",new JSONObject(f.inputs(run)));result.put("outputs",JavaModelSemantics.outputs(f.node(run),projection));result.put("rawOutput",projection.content());result.put("tokenCost",projection.usage());run.setLastEventSeq(3L);
        var accepted=new JSONArray();for(var saved:f.events.get(run.getId()))accepted.add(ModelMessageSources.sourceObject(saved.eventJson()));accepted.add(event);
        return f.sources.values(run,assignment.getJSONObject("dsl"),assignment.getJSONObject("dsl").getJSONArray("nodes").getJSONObject(2),accepted).get("answer");
    }
    @Test void actualFrozenHistoryMessagesAdmitPrepareAndRefillFromTerminalFrames()throws Exception {
        prior();var run=run(10,true);var request=request(run);assertEquals(List.of("system","user","assistant","user"),request.getJSONObject("parameters").getJSONArray("messages").stream().map(v->((JSONObject)v).get("role")).toList());
        calls.start(run.getId(),f.worker,request);var row=f.models.find(grant.get().operationId());var proof=f.snapshot(run);var facts=JSON.parseObject(row.getApprovalJson()).getJSONObject("candidate");assertEquals(RunJsonBoundary.canonicalFull(proof),facts.get("javaHistoryJson"));assertFalse(request.containsKey("javaHistoryJson"));
        assertTrue(policy.currentCall(candidate(row),new CallPermit(JSON.parseObject(row.getApprovalJson()).getString("fingerprint"),row.getApprovalRef(),row.getApprovalExpiresAt().toInstant(ZoneOffset.UTC))));
        commit(false);var round=f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE);assertEquals("COMPLETED",round.get("state"));var projection=JavaModelSemantics.projection(frames(false));assertEquals(projection.content(),JSON.parseObject((String)round.get("itemJson")).getJSONArray("llmResponses").getJSONObject(0).get("content"));assertEquals("COMPLETED",f.models.find(row.getId()).getState());
        var end=ModelMessageSources.sourceObject(run.getAssignmentJson()).getJSONObject("dsl").getJSONArray("nodes").getJSONObject(2);var node=f.node(run);var event=ModelOperationJson.copy(f.original.getJSONArray("actualEvents").stream().map(v->(JSONObject)v).filter(v->"node.completed".equals(v.get("eventType"))&&JavaRunHistoryPersistenceTest.NODE.equals(v.get("nodeId"))).findFirst().orElseThrow());event.put("runId",run.getId());event.put("leaseId",run.getLeaseId());event.put("seq",3);event.getJSONObject("payload").getJSONObject("result").put("inputs",new JSONObject(f.inputs(run)));var expected=JavaModelSemantics.outputs(node,projection);event.getJSONObject("payload").getJSONObject("result").put("outputs",expected);
        event.getJSONObject("payload").getJSONObject("result").put("rawOutput",projection.content());event.getJSONObject("payload").getJSONObject("result").put("tokenCost",projection.usage());run.setLastEventSeq(3L);
        var accepted=new JSONArray();for(var saved:f.events.get(run.getId()))accepted.add(ModelMessageSources.sourceObject(saved.eventJson()));accepted.add(event);
        assertEquals(projection.content(),f.sources.values(run,ModelMessageSources.sourceObject(run.getAssignmentJson()).getJSONObject("dsl"),end,accepted).get("answer"));
        assertEquals(RunJsonBoundary.canonicalFull(proof),JSON.parseObject(f.models.find(row.getId()).getApprovalJson()).getJSONObject("candidate").get("javaHistoryJson"));
    }
    @Test void forgedMessageRejectsBeforeLedgerOrDispatch()throws Exception {prior();var run=run(2,true);var req=request(run);req.getJSONObject("parameters").getJSONArray("messages").getJSONObject(2).put("content","伪造历史答案");assertEquals(403,assertThrows(ServiceException.class,()->calls.start(run.getId(),f.worker,req)).getCode());assertTrue(f.models.forRunResource(run.getId(),"model:1:version:2").isEmpty());assertNull(grant.get());}
    @Test void policyIndependentlyRejectsFakeReferenceHashHistoryAndScope()throws Exception {
        prior();var run=run(2,true);var row=calls.prepare(run.getId(),f.worker,request(run));var good=candidate(row);assertNotNull(policy.approveCall(good));
        for(String key:List.of("historyRef","historyHash","history")){var facts=ModelMessageSources.sourceObject(row.getApprovalJson()).getJSONObject("candidate");var proof=JSON.parseObject(facts.getString("javaHistoryJson"));proof.put(key,key.equals("history")?new JSONArray():"wrong");facts.put("javaHistoryJson",RunJsonBoundary.canonicalFull(proof));var method=ModelOperationService.class.getDeclaredMethod("callCandidate",JSONObject.class);method.setAccessible(true);var bad=(CallCandidate)method.invoke(null,facts);assertEquals(403,assertThrows(ServiceException.class,()->policy.approveCall(bad),key).getCode());}
        run.setLeaseId("changed-lease");assertEquals(403,assertThrows(ServiceException.class,()->policy.approveCall(good)).getCode());assertNull(grant.get());
    }
    @Test void lengthRetainsFailedProviderLedgerAndFillsOriginalSuccessfulReturn()throws Exception {prior();var run=run(1,true);calls.start(run.getId(),f.worker,request(run));commit(true);var operation=f.models.find(grant.get().operationId());assertEquals("FAILED",operation.getState());assertEquals("provider",operation.getFailureKind());assertEquals("COMPLETED",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));}
    @Test void failedCallLeavesTrustedHalfRoundOpenWithoutAssistant()throws Exception {var run=run(1,true);calls.start(run.getId(),f.worker,request(run));calls.recordFailure(grant.get(),new FailureFacts("transport","isolated-failure",true,true,false));assertEquals("EFFECT_UNKNOWN",f.models.find(grant.get().operationId()).getState());assertEquals("OPEN",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));assertTrue(JSON.parseObject((String)f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("itemJson")).getJSONArray("llmResponses").isEmpty());}
    @Test void missingOpenRoundAndMissingHistoryBeanCannotApproveNonzeroHistory()throws Exception {var run=run(1,false);var node=f.node(run);var p=JSONObject.of("resourceId","model:1:version:2","resourceVersion","2","provider","openai","modelName","original-model","mode","chat","messages",JavaModelSemantics.messages(node,f.inputs(run),new JSONArray()),"options",JavaModelSemantics.options(node));var req=JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"nodeId",JavaRunHistoryPersistenceTest.NODE,"iterationId",null,"operation","model.invoke","parameters",p,"idempotencyKey","no-history");assertEquals(409,assertThrows(ServiceException.class,()->calls.prepare(run.getId(),f.worker,req)).getCode());target.useHistory(JavaRunHistoryPersistenceTest.provider(null));assertEquals(503,assertThrows(ServiceException.class,()->calls.prepare(run.getId(),f.worker,req)).getCode());assertTrue(f.models.forRunResource(run.getId(),"model:1:version:2").isEmpty());}
    @Test void refillFailureKeepsCommittedModelTerminalAndProofButRejectsNodeResult()throws Exception {var run=run(0,true);calls.start(run.getId(),f.worker,request(run));var raw=frames(false);long seq=0;for(Object item:raw)calls.commitFrame(grant.get(),++seq,(JSONObject)item);var before=f.models.find(grant.get().operationId());var broken=spy(f.target);doThrow(new IllegalStateException("isolated-refill-failure")).when(broken).completeJava(anyString(),anyString(),anyString());target.useHistory(JavaRunHistoryPersistenceTest.provider(proxy(broken)));long last=seq;assertThrows(IllegalStateException.class,()->calls.finishStream(grant.get(),last,last-1,"stop"));var after=f.models.find(before.getId());assertEquals("COMPLETED",after.getState());assertTrue(after.getRevision()>before.getRevision());assertEquals(1,after.getStopConfirmed());assertEquals("stream-finished:"+after.getId()+":"+last+":"+(last-1),after.getStopProofId());assertEquals("OPEN",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));calls.recordFailure(grant.get(),new FailureFacts("transport","refill-failure",true,true,false));assertEquals("COMPLETED",f.models.find(after.getId()).getState());assertEquals(403,assertThrows(ServiceException.class,()->completedAnswer(run,raw)).getCode());}
    @Test void legacyTerminalWithContextWithoutRoundStillRequiresFullModelFacts()throws Exception {
        var run=run(0,false);target.useHistory(JavaRunHistoryPersistenceTest.provider(null));policy.useHistory(JavaRunHistoryPersistenceTest.provider(null),f.runs);calls.start(run.getId(),f.worker,zeroRequest(run));commit(false);
        var row=f.models.find(grant.get().operationId());assertNotNull(f.service.executionContext(run));assertNull(f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE));assertFalse(JSON.parseObject(row.getApprovalJson()).getJSONObject("candidate").containsKey("javaHistoryJson"));
        assertEquals(JavaModelSemantics.projection(frames(false)).content(),completedAnswer(run,frames(false)));
        target.useHistory(JavaRunHistoryPersistenceTest.provider(f.service));assertEquals(403,assertThrows(ServiceException.class,()->calls.finishStream(grant.get(),4,3,"stop")).getCode());assertNull(f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE));assertEquals("COMPLETED",f.models.find(row.getId()).getState());
        row.setStopProofId("not-the-real-stream-proof");f.models.update(row);assertEquals(403,assertThrows(ServiceException.class,()->completedAnswer(run,frames(false))).getCode());
    }
    @Test void legacyCandidateCannotFallbackWhenActualRoundExists()throws Exception {
        var run=run(0,false);target.useHistory(JavaRunHistoryPersistenceTest.provider(null));policy.useHistory(JavaRunHistoryPersistenceTest.provider(null),f.runs);calls.start(run.getId(),f.worker,zeroRequest(run));commit(false);f.open(run);
        assertEquals("OPEN",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));assertEquals(403,assertThrows(ServiceException.class,()->completedAnswer(run,frames(false))).getCode());
    }
    @Test void actualFramesReadRecoversCommittedTerminalOpenRoundWithoutRedispatch()throws Exception {
        var run=run(0,true);calls.start(run.getId(),f.worker,request(run));var raw=frames(false);long seq=0;for(Object item:raw)calls.commitFrame(grant.get(),++seq,(JSONObject)item);
        var broken=spy(f.target);doThrow(new IllegalStateException("isolated-callback-gap")).when(broken).completeJava(anyString(),anyString(),anyString());target.useHistory(JavaRunHistoryPersistenceTest.provider(proxy(broken)));long last=seq;assertThrows(IllegalStateException.class,()->calls.finishStream(grant.get(),last,last-1,"stop"));assertEquals("COMPLETED",f.models.find(grant.get().operationId()).getState());assertEquals("OPEN",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));
        target.useHistory(JavaRunHistoryPersistenceTest.provider(f.service));var ack=calls.frames(run.getId(),f.worker,grant.get().operationId(),JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"afterCursor",0,"limit",64));assertTrue(ack.getBooleanValue("done"));assertEquals("COMPLETED",ack.get("state"));assertEquals(raw,ack.getJSONArray("frames"));assertEquals("COMPLETED",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));assertEquals(1,dispatches.get());assertEquals(JavaModelSemantics.projection(raw).content(),completedAnswer(run,raw));
        var again=calls.frames(run.getId(),f.worker,grant.get().operationId(),JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"afterCursor",last,"limit",64));assertTrue(again.getBooleanValue("done"));assertEquals(1,dispatches.get());
    }
    @Test void reachableWholeHistoryItemBudgetFailurePreservesAccurateProviderCompletion()throws Exception {
        var params=f.params("系统","q".repeat(200000),0);params.put("maxTokens",600000);var run=f.run("值",params,JavaRunHistoryPersistenceTest.CHAT,42,1,2);run.setDeadline(LocalDateTime.ofInstant(Instant.now().plusSeconds(300),ZoneOffset.UTC));var task=ModelMessageSources.sourceObject(run.getAssignmentJson());run.setModelPermitJson(RunJsonBoundary.canonicalFull(calls.admit(run.getId(),42,1,3,task.getString("dslHash"),task.getJSONObject("input"),task.getJSONObject("resourceSnapshots"),task.getJSONObject("dsl"),run.getDeadline().toInstant(ZoneOffset.UTC),"java")));f.open(run);calls.start(run.getId(),f.worker,request(run));assertEquals(600000,JSON.parseObject(f.models.find(grant.get().operationId()).getParametersJson()).getJSONObject("options").getIntValue("maxTokens"));
        var original=frames(false);long seq=0;for(int i=0;i<50;i++){var chunk=ModelOperationJson.copy(original.getJSONObject(0));chunk.getJSONArray("choices").getJSONObject(0).put("delta",JSONObject.of("role","assistant","content","a".repeat(40000)));calls.commitFrame(grant.get(),++seq,chunk);}calls.commitFrame(grant.get(),++seq,original.getJSONObject(2));calls.commitFrame(grant.get(),++seq,original.getJSONObject(3));
        var round=f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE);var item=JSON.parseObject((String)round.get("itemJson"));item.getJSONArray("llmResponses").add(JSONObject.of("role","ASSISTANT","content","a".repeat(2000000),"timestamp",1));assertTrue(RunJsonBoundary.canonicalFull(item).getBytes(java.nio.charset.StandardCharsets.UTF_8).length>RunProtocolLimits.RESULT_BYTES);
        long last=seq;assertEquals(413,assertThrows(ServiceException.class,()->calls.finishStream(grant.get(),last,last-1,"stop")).getCode());var terminal=f.models.find(grant.get().operationId());assertEquals("COMPLETED",terminal.getState());assertEquals(1,terminal.getStopConfirmed());assertNotNull(terminal.getStopProofId());assertEquals("OPEN",f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE).get("state"));calls.recordFailure(grant.get(),new FailureFacts("transport","history-budget-failure",true,true,false));assertEquals("COMPLETED",f.models.find(terminal.getId()).getState());
        assertEquals(413,assertThrows(ServiceException.class,()->calls.frames(run.getId(),f.worker,terminal.getId(),JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"afterCursor",0,"limit",64))).getCode());assertEquals("COMPLETED",f.models.find(terminal.getId()).getState());assertEquals(1,dispatches.get());
    }
    @Test void newZeroHistoryContextCannotPrepareWithoutOpenedRound()throws Exception {
        var run=run(0,false);assertEquals(409,assertThrows(ServiceException.class,()->calls.prepare(run.getId(),f.worker,zeroRequest(run))).getCode());assertTrue(f.models.forRunResource(run.getId(),"model:1:version:2").isEmpty());assertEquals(0,dispatches.get());
    }
    @Test void zeroHistoryWithoutContextKeepsOriginalNoBeanPath()throws Exception {var run=run(0,false);try(var sql=f.connection.prepareStatement("DELETE FROM paiflow_run_context WHERE run_id=?")){sql.setString(1,run.getId());sql.executeUpdate();}target.useHistory(JavaRunHistoryPersistenceTest.provider(null));var n=f.node(run);var p=JSONObject.of("resourceId","model:1:version:2","resourceVersion","2","provider","openai","modelName","original-model","mode","chat","messages",JavaModelSemantics.messages(n,f.inputs(run),new JSONArray()),"options",JavaModelSemantics.options(n));var req=JSONObject.of("leaseId",run.getLeaseId(),"attempt",1,"nodeId",JavaRunHistoryPersistenceTest.NODE,"iterationId",null,"operation","model.invoke","parameters",p,"idempotencyKey","old-zero");calls.start(run.getId(),f.worker,req);assertFalse(JSON.parseObject(f.models.find(grant.get().operationId()).getApprovalJson()).getJSONObject("candidate").containsKey("javaHistoryJson"));commit(false);assertNull(f.rows.javaRound(run.getId(),1,JavaRunHistoryPersistenceTest.NODE));}
}
